#!/usr/bin/env bash
set -euo pipefail
study=benchmarks/zenmath_pow_opt_2026-11-06
out=$1
mkdir "$out"
profile=frozen-native-policy/binaries/2fade8efb49de038-profile
cc -O3 -fno-fast-math "$study/profile-c.c" -ldl -lm -o "$out/profile-c"
# One shared serialized input corpus, generated by the same Rust source as the
# retained timing executable. The input binary is only an untimed corpus writer.
"$CARGO_TARGET_DIR/release/input" gamma-decode "$out/decode.pow32le"
for mode in off on; do
    perf stat -e cycles,instructions,branches,branch-misses -o "$out/c-$mode.stat" -- "$out/profile-c" "$(pwd)/c-control/core-v3-$mode.so" cr_powf "$out/decode.pow32le" 1000 > "$out/c-$mode.stdout"
    perf record -F 999 -g -o "$out/c-$mode.perf.data" -- "$out/profile-c" "$(pwd)/c-control/core-v3-$mode.so" cr_powf "$out/decode.pow32le" 1000 > "$out/c-$mode-record.stdout" 2> "$out/c-$mode-record.log"
    perf report --stdio -i "$out/c-$mode.perf.data" > "$out/c-$mode.report"
done
for label in direct-v3/correct ordinary/correct current/midp-pre-fused current/lowp-pre-separate packed-v3/correct; do
    key=${label//\//-}
    for variant in per-value uniform; do
        extra=()
        if [[ "$variant" == uniform ]]; then extra=(--uniform); fi
        perf stat -e cycles,instructions,branches,branch-misses -o "$out/rust-$key-$variant.stat" -- "$profile" gamma-decode "$label" 1000 "${extra[@]}" > "$out/rust-$key-$variant.stdout"
        perf record -F 999 -g -o "$out/rust-$key-$variant.perf.data" -- "$profile" gamma-decode "$label" 1000 "${extra[@]}" > "$out/rust-$key-$variant-record.stdout" 2> "$out/rust-$key-$variant-record.log"
        perf report --stdio -i "$out/rust-$key-$variant.perf.data" > "$out/rust-$key-$variant.report"
    done
done
sha256sum "$out/profile-c" "$out/decode.pow32le" c-control/* > "$out/source-binary.sha256"
